def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    r, c = next((i, j) for i in range(h) for j in range(w) if grid[i][j] == 3)

    # The mark traces an outward square spiral: up, right, down, left.
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length = 2
    d = 0

    # Continue the spiral beyond the grid too, since later segments can re-enter it.
    for _ in range(4 * (max(h, w) + 5)):
        dr, dc = directions[d]
        for _ in range(length):
            r += dr
            c += dc
            if 0 <= r < h and 0 <= c < w:
                if grid[r][c] == 2:
                    return out
                if out[r][c] == 0:
                    out[r][c] = 3
        d = (d + 1) % 4
        if d % 2 == 0:
            length += 2

    return out
